############################################################
# TOPOLOGY SPACE TRANSFORMATION ANALYSIS
#
# Goal:
# Quantify how ecological dynamics transform the
# topology space generated by different food-web
# reconstruction frameworks.
############################################################

#------1. Load libraries -------------------------------------------------------

library(tidyverse)
library(vegan)
library(emmeans)
library(patchwork)
library(ggrepel)
library(genzplyr)
library(geomorph)
library(circular)
library(RVAideMemoire)
library(vegan)
library(tidytext)

source("lib/plotting_theme.R")

set.seed(66)

#------2. Load data ------------------------------------------------------------

pre_df <-
  read_csv("outputs/topology_initial.csv") %>%
  na.omit()

post_df <-
  read_csv("outputs/topology_END.csv") %>%
  yeet(!is.na(richness)) %>%
  yeet(richness > 0) %>%
  na.omit()


stability_meta <- read_csv("outputs/stability_metrics.csv", show_col_types = FALSE) %>%
  mutate(Model = factor(Model, levels = model_order))

# keep only stable networks
valid_ids <- stability_meta %>%
  yeet(run_issues == "success") %>%
  main_character(fw_ID)

pre_df <-
  pre_df %>%
  yeet(fw_ID %in% valid_ids)

post_df <-
  post_df %>%
  yeet(fw_ID %in% valid_ids)

# combine
combined <-
  bind_rows(
    pre_df %>%
      mutate(state = "Pre"),
    post_df %>%
      mutate(state = "Post")
  )

# define topo vars
topo_vars <-
  combined %>%
  vibe_check(-fw_ID, -model, -state) %>%
  names()

#------4. PCA ------------------------------------------------------------------

pca <- prcomp(combined[, topo_vars],
              center = TRUE,
              scale. = TRUE)

scores <- as.data.frame(pca$x[,1:5])

topology_space <- bind_cols(combined[,c("fw_ID","model","state")],
                            scores) %>%
  glow_up(state = factor(state, levels = c("Pre", "Post")))

#------5. PERMANOVA ------------------------------------------------------------

# subset pre state and run PERMANOVA
pre_space <- topology_space %>%
  yeet(state == "Pre")
pre_dist  <- vegdist(pre_space[, c("PC1", "PC2", "PC3", "PC4", "PC5")], 
                     method = "euclidean")

permanova_pre <- adonis2(pre_dist ~ model, data = pre_space, permutations = 999)
print(permanova_pre)

# Subset post state and run PERMANOVA
post_space <- topology_space %>% 
  yeet(state == "Post")
post_dist  <- vegdist(post_space[, c("PC1", "PC2", "PC3", "PC4", "PC5")], 
                      method = "euclidean")

permanova_post <- adonis2(post_dist ~ model, data = post_space, permutations = 999)
print(permanova_post)

library(pairwiseAdonis)

# Pairwise comparisons for Pre state
pairwise_pre <- pairwise.adonis2(pre_dist ~ model, data = pre_space, p.adjust.m = "bonferroni")
print(pairwise_pre)

# Pairwise comparisons for Post state
pairwise_post <- pairwise.adonis2(post_dist ~ model, data = post_space, p.adjust.m = "bonferroni")
print(pairwise_post)

# Check group dispersions for Pre state
disp_pre <- betadisper(pre_dist, pre_space$model)
tukey_pre <- TukeyHSD(disp_pre)
print(tukey_pre)

# Check group dispersions for Post state
disp_post <- betadisper(post_dist, post_space$model)
tukey_post <- TukeyHSD(disp_post)
print(tukey_post)

# Plot to visualize centroids and dispersion
plot(disp_pre)
plot(disp_post)

#------6. Variance expalined ---------------------------------------------------

variance_explained <-
  tibble(
    PC = seq_along(pca$sdev),
    variance =
      100 *
      pca$sdev^2 /
      sum(pca$sdev^2)
  )

variance_explained

# FIGURE 1
# common topo space

fig_space <-
